require('dotenv').config();
const path = require('path');
const express = require('express');
const mongoose = require('mongoose');
const itemRoutes = require('./routes/itemRoutes');
 
const app = express();
 
app.use(express.json());
app.use(express.static(path.join(__dirname, 'public'))); // serves index.html, style.css, app.js
app.get('/about', (_req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'about.html'));
});
app.get('/api/health', async (_req, res) => {
  try {
    if (!process.env.MONGO_URI) {
      return res.status(503).json({
        database: 'MongoDB',
        status: 'offline',
        reason: 'MONGO_URI is not set',
      });
    }
    const readyState = mongoose.connection.readyState;
    if (readyState === 2) {
      return res.status(503).json({ database: 'MongoDB', status: 'connecting', readyState });
    }
    if (readyState !== 1 || !mongoose.connection.db) {
      return res.status(503).json({
        database: 'MongoDB',
        status: 'offline',
        readyState,
        reason: 'not connected',
      });
    }
    await mongoose.connection.db.command({ ping: 1 });
    return res.json({ database: 'MongoDB', status: 'online', readyState });
  } catch {
    return res.status(503).json({
      database: 'MongoDB',
      status: 'offline',
      reason: 'connection failed',
    });
  }
});
app.use('/api/items', itemRoutes);
 
const PORT = process.env.PORT || 5000;
 
app.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));

mongoose
  .connect(process.env.MONGO_URI)
  .then(() => console.log('Connected to MongoDB'))
  .catch((err) => console.error('MongoDB connection error:', err));
